<!-- This file is generated by AI. -->
<!--
  添加参考音频对话框: 只处理"这一条要加什么" —— 选文件 → 填参考文本与语言 → 确认。

  列表本身不在这里展示: 它就在「编辑角色」对话框里, 再弹一个同样的列表纯属重复,
  用户还得在两个几乎一样的界面之间来回找。

  音频过长时接一个裁剪对话框 (展示波形与自动建议区间); 过短则由后端静默补尾。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->
<script lang="ts">
  import { open as openDialog } from '@tauri-apps/plugin-dialog';
  import { untrack } from 'svelte';

  import { voiceAddReference, type Character, type ReferenceAudio } from '../commands/voice';
  import { appStore } from '../state/store.svelte';
  import { voiceController } from '../voice/controller';
  import { errorSummary } from '../voice/errorText';
  import { LANGUAGE_LABELS } from '../voice/types';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import Select from './Select.svelte';
  import TrimAudioDialog from './TrimAudioDialog.svelte';

  let {
    character,
    onClose,
    /** 添加成功 (已经把新条目并入全局角色列表) */
    onAdded,
  }: {
    character: Character;
    onClose: () => void;
    onAdded: (added: ReferenceAudio) => void;
  } = $props();

  let source = $state('');
  let text = $state('');
  /** 语言初值取角色的当前语言, 之后完全由用户接管 */
  let language = $state(untrack(() => character.language || 'zh'));
  let busy = $state(false);
  let error = $state<string | null>(null);
  /** 待裁剪区间 (非 null 时显示裁剪对话框) */
  let trim = $state<{ start: number; end: number } | null>(null);

  const languageOptions = $derived(Object.entries(LANGUAGE_LABELS).map(([value, label]) => ({ value, label })));

  async function pickFile(): Promise<void> {
    error = null;
    const picked = await openDialog({ multiple: false, filters: [{ name: '音频', extensions: ['wav'] }] });
    if (typeof picked === 'string') source = picked;
  }

  /** 确认添加: 过长时先进入裁剪, 否则直接入库 */
  async function confirm(): Promise<void> {
    if (!source.trim() || !text.trim()) return;
    busy = true;
    error = null;
    try {
      const info = await voiceController.inspectAudio(source);
      if (info.tooLong) {
        const suggestion = await voiceController.trimSuggestion(source);
        trim = { start: suggestion.suggested.start, end: suggestion.suggested.end };
        return;
      }
      await add(source, undefined, undefined);
    } catch (caught) {
      error = errorSummary(String(caught));
    } finally {
      busy = false;
    }
  }

  /**
   * 真正入库。
   *
   * 自己兜住异常: 裁剪对话框的「确认」直接调用它, 走不到 `confirm` 的 try —— 不接就是一个
   * 静默的未处理 rejection, 用户点了确认却什么都没发生。失败时保留裁剪对话框以便重试。
   */
  async function add(path: string, start?: number, end?: number): Promise<void> {
    busy = true;
    error = null;
    try {
      const updated = await voiceAddReference(character.id, {
        source: path,
        text: text.trim(),
        language,
        tags: [],
        start,
        end,
      });
      voiceController.setCharacters(appStore.voiceCharacters.map((item) => (item.id === updated.id ? updated : item)));
      trim = null;
      // `voice_add_reference` 把新条目追加在末尾, 因此最后一条就是刚加进来的
      const added = updated.references[updated.references.length - 1];
      onClose();
      if (added) onAdded(added);
    } catch (caught) {
      error = errorSummary(String(caught));
    } finally {
      busy = false;
    }
  }

  const ready = $derived(source.trim().length > 0 && text.trim().length > 0 && !busy);
</script>

<AppDialog
  title={`添加参考音频 · ${character.name}`}
  description="参考文本必须与音频逐字一致；时长须在 3~10 秒之间。"
  size="form"
  height={360}
  {onClose}
>
  <div class="reference-add-form">
    <div class="voice-field">
      <span class="voice-label">音频文件</span>
      <div class="input-row">
        <input class="ui-input" value={source} readonly placeholder="选择一段 3~10 秒的清晰人声" title={source} />
        <Button icon="Folder" title="选择音频文件" onclick={() => void pickFile()} />
      </div>
    </div>

    <!-- 语言取值很短, 固定窄宽度, 不参与拉伸 -->
    <label class="voice-field reference-add-language">
      <span class="voice-label">语言</span>
      <Select
        value={language}
        title="参考文本使用的语言"
        options={languageOptions}
        onchange={(value) => (language = value)}
      />
    </label>

    <label class="voice-field">
      <span class="voice-label">
        参考文本
        <span class="voice-required">*</span>
        <span class="voice-label-note">必须与音频逐字一致</span>
      </span>
      <input
        class="ui-input"
        value={text}
        placeholder="例如：我有什么不对劲的地方吗？"
        oninput={(event) => (text = event.currentTarget.value)}
      />
    </label>

    {#if error}
      <p class="voice-error">{error}</p>
    {/if}
  </div>

  {#snippet footer()}
    <Button disabled={busy} onclick={onClose}>取消</Button>
    <Button appearance="primary" disabled={!ready} onclick={() => void confirm()}>
      {busy ? '处理中…' : '添加'}
    </Button>
  {/snippet}
</AppDialog>

{#if trim}
  <TrimAudioDialog
    path={source}
    suggestedStart={trim.start}
    suggestedEnd={trim.end}
    {text}
    {language}
    requireText={false}
    {busy}
    {error}
    onTextChange={(next) => (text = next)}
    onLanguageChange={(next) => (language = next)}
    onCancel={() => (trim = null)}
    onConfirm={(start, end) => void add(source, start, end)}
  />
{/if}
